from sklearn.compose import ColumnTransformer
from sklearn.ensemble import HistGradientBoostingClassifier, HistGradientBoostingRegressor
from sklearn.impute import SimpleImputer
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import OneHotEncoder, FunctionTransformer
import pandas as pd
import numpy as np


def add_features(X):
    if isinstance(X, np.ndarray):
        X = pd.DataFrame(X)
    else:
        X = X.copy()

    # Ensure numeric types
    for col in ["area", "bathrooms", "bedrooms", "stories"]:
        if col in X.columns:
            X[col] = pd.to_numeric(X[col], errors="coerce").fillna(0)

    if "area" in X.columns and "bathrooms" in X.columns:
        X["area_per_bathroom"] = X["area"] / (X["bathrooms"] + 1e-5)
    if "area" in X.columns and "bedrooms" in X.columns:
        X["area_per_bedroom"] = X["area"] / (X["bedrooms"] + 1e-5)
    if "bedrooms" in X.columns and "bathrooms" in X.columns:
        X["total_rooms"] = X["bedrooms"] + X["bathrooms"]
        if "area" in X.columns:
            X["area_per_room"] = X["area"] / (X["total_rooms"] + 1e-5)

    return X


def build_pipeline(profile: dict):
    columns = profile["columns"]
    numeric = [c["name"] for c in columns if c["kind"] == "numeric"]
    categorical = [c["name"] for c in columns if c["kind"] in ("categorical", "boolean")]

    # Add engineered features to numeric list
    numeric.extend(["area_per_bathroom", "area_per_bedroom", "total_rooms", "area_per_room"])

    transformers = []
    if numeric:
        transformers.append(("num", SimpleImputer(strategy="median"), numeric))
    if categorical:
        cat = Pipeline(
            [
                ("impute", SimpleImputer(strategy="most_frequent")),
                ("onehot", OneHotEncoder(handle_unknown="ignore", sparse_output=False, max_categories=30)),
            ]
        )
        transformers.append(("cat", cat, categorical))

    preprocess = ColumnTransformer(transformers, remainder="drop")

    if profile["problem_type"] == "regression":
        model = HistGradientBoostingRegressor(random_state=0)
    else:
        model = HistGradientBoostingClassifier(random_state=0)

    return Pipeline([
        ("feature_engineering", FunctionTransformer(add_features)),
        ("preprocess", preprocess),
        ("model", model)
    ])


